sp_widget.client_script:
api.spinner = true;
api.server.get().then(function(response) {
    api.data.employees = response.data.result || [];
    api.spinner = false;
});

sp_widget.script:
(function() {
    data.result = [];
    try {
        var gr = new GlideRecord('x_1850353_employ_0_employee');
        gr.addQuery('active', true);
        gr.orderByDesc('sys_created_on');
        gr.setLimit(50);
        gr.query();
        while (gr.next()) {
            data.result.push({
                sys_id: gr.getUniqueValue(),
                name: gr.getDisplayValue('name'),
                email: gr.getDisplayValue('email'),
                department: gr.getDisplayValue('department'),
                joining_date: gr.getDisplayValue('joining_date'),
                status: gr.getDisplayValue('status')
            });
        }
    } catch(e) {
        gs.error('Employee Dashboard widget error: ' + e.message);
    }
})();
